// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/admin/content-requests", wrapper.ListContentRequests)
	m.HandleFunc("GET "+options.BaseURL+"/admin/flags", wrapper.ListFlags)
	m.HandleFunc("GET "+options.BaseURL+"/admin/invites", wrapper.ListInvites)
	m.HandleFunc("POST "+options.BaseURL+"/admin/invites", wrapper.CreateInvite)
	m.HandleFunc("GET "+options.BaseURL+"/admin/learners", wrapper.ListLearners)
	m.HandleFunc("POST "+options.BaseURL+"/admin/questions/{questionId}/retire", wrapper.RetireQuestion)
	m.HandleFunc("POST "+options.BaseURL+"/auth/dev-login", wrapper.DevLogin)
	m.HandleFunc("GET "+options.BaseURL+"/auth/google/callback", wrapper.GoogleCallback)
	m.HandleFunc("GET "+options.BaseURL+"/auth/google/login", wrapper.GoogleLogin)
	m.HandleFunc("POST "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc("GET "+options.BaseURL+"/concepts/{conceptId}", wrapper.GetConcept)
	m.HandleFunc("GET "+options.BaseURL+"/courses", wrapper.ListCourses)
	m.HandleFunc("GET "+options.BaseURL+"/courses/{courseId}", wrapper.GetCourse)
	m.HandleFunc("GET "+options.BaseURL+"/courses/{courseId}/exams", wrapper.ListExams)
	m.HandleFunc("GET "+options.BaseURL+"/courses/{courseId}/format-report", wrapper.GetFormatReport)
	m.HandleFunc("DELETE "+options.BaseURL+"/courses/{courseId}/learning-path", wrapper.AbandonLearningPath)
	m.HandleFunc("GET "+options.BaseURL+"/courses/{courseId}/learning-path", wrapper.GetLearningPath)
	m.HandleFunc("POST "+options.BaseURL+"/courses/{courseId}/learning-path", wrapper.StartLearningPath)
	m.HandleFunc("GET "+options.BaseURL+"/courses/{courseId}/mastery", wrapper.GetMastery)
	m.HandleFunc("GET "+options.BaseURL+"/courses/{courseId}/recommendations", wrapper.GetRecommendations)
	m.HandleFunc("GET "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc("POST "+options.BaseURL+"/questions/{questionId}/flags", wrapper.FlagQuestion)
	m.HandleFunc("POST "+options.BaseURL+"/sessions", wrapper.CreateSession)
	m.HandleFunc("GET "+options.BaseURL+"/sessions/{sessionId}", wrapper.GetSession)
	m.HandleFunc("POST "+options.BaseURL+"/sessions/{sessionId}/answers", wrapper.SubmitAnswer)
	m.HandleFunc("POST "+options.BaseURL+"/sessions/{sessionId}/finish", wrapper.FinishSession)
	m.HandleFunc("GET "+options.BaseURL+"/sessions/{sessionId}/next", wrapper.GetNextQuestion)
	m.HandleFunc("GET "+options.BaseURL+"/sessions/{sessionId}/result", wrapper.GetSessionResult)

	return m
}

