// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /admin/content-requests)
	ListContentRequests(ctx context.Context, request ListContentRequestsRequestObject) (ListContentRequestsResponseObject, error)

	// (GET /admin/flags)
	ListFlags(ctx context.Context, request ListFlagsRequestObject) (ListFlagsResponseObject, error)

	// (GET /admin/invites)
	ListInvites(ctx context.Context, request ListInvitesRequestObject) (ListInvitesResponseObject, error)

	// (POST /admin/invites)
	CreateInvite(ctx context.Context, request CreateInviteRequestObject) (CreateInviteResponseObject, error)

	// (GET /admin/learners)
	ListLearners(ctx context.Context, request ListLearnersRequestObject) (ListLearnersResponseObject, error)

	// (POST /admin/questions/{questionId}/retire)
	RetireQuestion(ctx context.Context, request RetireQuestionRequestObject) (RetireQuestionResponseObject, error)
	// Local dev and e2e only (AUTH_DEV_LOGIN=true). Creates the Learner if missing.
	// (POST /auth/dev-login)
	DevLogin(ctx context.Context, request DevLoginRequestObject) (DevLoginResponseObject, error)

	// (GET /auth/google/callback)
	GoogleCallback(ctx context.Context, request GoogleCallbackRequestObject) (GoogleCallbackResponseObject, error)
	// Redirect to Google OIDC. Optional invite token is carried through the state.
	// (GET /auth/google/login)
	GoogleLogin(ctx context.Context, request GoogleLoginRequestObject) (GoogleLoginResponseObject, error)

	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Concept with its Lesson, Prerequisites, dependents and the Learner's Mastery.
	// (GET /concepts/{conceptId})
	GetConcept(ctx context.Context, request GetConceptRequestObject) (GetConceptResponseObject, error)

	// (GET /courses)
	ListCourses(ctx context.Context, request ListCoursesRequestObject) (ListCoursesResponseObject, error)
	// Course with its full knowledge graph (Topics, active Concepts, Prerequisites).
	// (GET /courses/{courseId})
	GetCourse(ctx context.Context, request GetCourseRequestObject) (GetCourseResponseObject, error)

	// (GET /courses/{courseId}/exams)
	ListExams(ctx context.Context, request ListExamsRequestObject) (ListExamsResponseObject, error)

	// (GET /courses/{courseId}/format-report)
	GetFormatReport(ctx context.Context, request GetFormatReportRequestObject) (GetFormatReportResponseObject, error)

	// (DELETE /courses/{courseId}/learning-path)
	AbandonLearningPath(ctx context.Context, request AbandonLearningPathRequestObject) (AbandonLearningPathResponseObject, error)
	// The Learner's active Learning Path in this Course, if any.
	// (GET /courses/{courseId}/learning-path)
	GetLearningPath(ctx context.Context, request GetLearningPathRequestObject) (GetLearningPathResponseObject, error)
	// Start a Learning Path from a Recommendation. Replaces any active one.
	// (POST /courses/{courseId}/learning-path)
	StartLearningPath(ctx context.Context, request StartLearningPathRequestObject) (StartLearningPathResponseObject, error)
	// The current Learner's Mastery for every Concept in the Course (Mastery Map data).
	// (GET /courses/{courseId}/mastery)
	GetMastery(ctx context.Context, request GetMasteryRequestObject) (GetMasteryResponseObject, error)
	// Recommendations ordered by Priority (first is the top Recommendation).
	// (GET /courses/{courseId}/recommendations)
	GetRecommendations(ctx context.Context, request GetRecommendationsRequestObject) (GetRecommendationsResponseObject, error)

	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Flag a Question the Learner has answered. Pulls it for every Learner.
	// (POST /questions/{questionId}/flags)
	FlagQuestion(ctx context.Context, request FlagQuestionRequestObject) (FlagQuestionResponseObject, error)
	// Start a Quiz, Diagnostic Quiz, Placement Test, or Exam.
	// (POST /sessions)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)

	// (GET /sessions/{sessionId})
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)

	// (POST /sessions/{sessionId}/answers)
	SubmitAnswer(ctx context.Context, request SubmitAnswerRequestObject) (SubmitAnswerResponseObject, error)

	// (POST /sessions/{sessionId}/finish)
	FinishSession(ctx context.Context, request FinishSessionRequestObject) (FinishSessionResponseObject, error)
	// Next unanswered Question (no answer key). 204 when the session has no more Questions.
	// (GET /sessions/{sessionId}/next)
	GetNextQuestion(ctx context.Context, request GetNextQuestionRequestObject) (GetNextQuestionResponseObject, error)

	// (GET /sessions/{sessionId}/result)
	GetSessionResult(ctx context.Context, request GetSessionResultRequestObject) (GetSessionResultResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListContentRequests operation middleware
func (sh *strictHandler) ListContentRequests(w http.ResponseWriter, r *http.Request) {
	var request ListContentRequestsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListContentRequests(ctx, request.(ListContentRequestsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListContentRequests")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListContentRequestsResponseObject); ok {
		if err := validResponse.VisitListContentRequestsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

